{
  "title": "寻龙记",
  "scene": "村庄口，石碑上刻着奇怪的符号。前方是密林，似乎有条小径蜿蜒其中。村长说，通往龙潭的路在小径尽头，但路途艰险，有巨蟒和陷阱。",
  "goal": "找到通往龙潭的路，避开危险。",
  "clue": "石碑上的符号暗示龙潭方向，小径旁散落的枯叶上有模糊的脚印。",
  "choices": [
    {"id": "A", "text": "跟随小径前进", "outcome": "小径两侧的枯叶被风吹动，脚印显示巨蟒曾经过此。继续前行，遇到了几只巨蟒，但躲过了陷阱，最终找到了龙潭入口。", "result": "success", "next": "next_level"},
    {"id": "B", "text": "在林中寻找捷径", "outcome": "选择了一条看似捷径的小路，但很快发现枯叶上的脚印是陷阱的标记，险些被陷进泥潭。勉强脱险后，浪费了宝贵的搜索时间。", "result": "partial", "next": "retry"},
    {"id": "C", "text": "返回村中询问长者", "outcome": "村长建议绕路，虽然绕远，却避免了险境。虽然没有直接找到龙潭，但也学习到了更多关于龙潭的秘密。", "result": "fail", "next": "next_level"}
  ]
}
